update public.spots set ref_id = 279, practice = '{"kitesurf": "D", "wingfoil": "P", "surf": "?"}'::jsonb, sports = '{"foil","kitesurf","wingfoil"}', rules = 'Wing signalé, mais fenêtre de profondeur et accès à vérifier. Dans la réserve naturelle, kite interdit et wing autorisé sous réserve des autres règles du périmètre. Kite documenté au nord de la plage, distinct de la réserve où le kite est interdit. Vérifier la carte de la réserve et le balisage.', sources = '{"hauts-de-france.developpement-durable.gouv.fr","theridery.com","villeducrotoy.fr","windnow.app","wyvoh.fr"}', notes = case when coalesce(notes, '') = '' then 'Kite documenté au nord de la plage, distinct de la réserve où le kite est interdit. Le wing reste une piste au Crotoy, faute de profondeur et de fenêtre validées. Vérifier la carte de la réserve et le balisage. Kite au nord de la plage selon la Ville, par SO à NO et autour de la pleine mer selon le guide. Wing signalé, mais fenêtre de profondeur et accès à vérifier. Dans la réserve naturelle, kite interdit et wing autorisé sous réserve des autres règles du périmètre. Kite au nord de la plage. Wing et profondeur à vérifier.' when notes like '%' || 'Kite documenté au nord de la plage, dist' || '%' then notes else notes || ' — ' || 'Kite documenté au nord de la plage, distinct de la réserve où le kite est interdit. Le wing reste une piste au Crotoy, faute de profondeur et de fenêtre validées. Vérifier la carte de la réserve et le balisage. Kite au nord de la plage selon la Ville, par SO à NO et autour de la pleine mer selon le guide. Wing signalé, mais fenêtre de profondeur et accès à vérifier. Dans la réserve naturelle, kite interdit et wing autorisé sous réserve des autres règles du périmètre. Kite au nord de la plage. Wing et profondeur à vérifier.' end where id = 'le-crotoy';
